(()=>{
'use strict';
const D=window.CMMI_DATA, $=s=>document.querySelector(s);if(!D){document.body.textContent='Contenu pédagogique indisponible';return;}
const STORE='cmmi_academy_2027_v1';
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',zap:'<path d="m13 2-3 8h7l-6 12 1-9H5z"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10"/><path d="m9 12 2 2 4-4"/>',repeat:'<path d="m17 2 4 4-4 4"/><path d="M3 11V9a3 3 0 0 1 3-3h15"/><path d="m7 22-4-4 4-4"/><path d="M21 13v2a3 3 0 0 1-3 3H3"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chart:'<path d="M3 3v18h18"/><path d="m6 15 4-4 4 3 6-7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06-2 2-.07-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21h-3v-.1A1.65 1.65 0 0 0 10.8 19a1.65 1.65 0 0 0-1.82.33l-.06.06-2-2 .06-.07A1.65 1.65 0 0 0 7.3 15.5a1.65 1.65 0 0 0-1.51-1H5v-3h.1A1.65 1.65 0 0 0 7 10.4a1.65 1.65 0 0 0-.33-1.82l-.06-.06 2-2 .07.06a1.65 1.65 0 0 0 1.82.33A1.65 1.65 0 0 0 11.5 5.4V5h3v.1A1.65 1.65 0 0 0 15.5 7a1.65 1.65 0 0 0 1.82-.33l.06-.06 2 2-.06.07a1.65 1.65 0 0 0-.33 1.82 1.65 1.65 0 0 0 1.51 1H21v3h-.1A1.65 1.65 0 0 0 19.4 15z"/>',check:'<path d="m4 12 5 5L20 6"/>',arrow:'<path d="m5 12 14 0m-6-6 6 6-6 6"/>',back:'<path d="m19 12-14 0m6-6-6 6 6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',trophy:'<path d="M8 21h8m-4-4v4M7 4h10v7a5 5 0 0 1-10 0z"/><path d="M7 6H4v3a3 3 0 0 0 3 3m10-6h3v3a3 3 0 0 1-3 3"/>',flame:'<path d="M12 22c4.4 0 7-3 7-7 0-3-2-6-4-7 0 3-2 4-3 4 0-5-1-7-3-10 0 4-4 7-4 13 0 4 2.7 7 7 7"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',search:'<circle cx="10.8" cy="10.8" r="7"/><path d="m16 16 5 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',upload:'<path d="M12 17V5m-4 4 4-4 4 4M4 17v4h16v-4"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',external:'<path d="M14 3h7v7M10 14 21 3"/><path d="M21 13v7a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h7"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 16v-4m0-4h.01"/>',star:'<path d="m12 2 3.1 6.3 7 1-5 5 .9 7.1-6-3.3-6 3.3L7 14.3l-5-5 7-1z"/>'};
const ico=(n,size=18)=>`<svg class="icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.info}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA');
const defaultState=()=>({completed:[],attempts:{},scores:[],activity:{},lastDay:null,streak:0,xp:0,flash:{},auditAnswers:{},auditNotes:{},auditMatrix:{},lessonMissions:{},lessonVisited:{},settings:{track:'enterprise',target:'',level:'3'},firstSeen:Date.now()});
function readState(){try{const old=JSON.parse(localStorage.getItem(STORE));if(!old)return defaultState();let x={...defaultState(),...old};x.settings={...defaultState().settings,...old.settings};return x}catch{return defaultState()}}let S=readState();
const save=()=>{try{localStorage.setItem(STORE,JSON.stringify(S))}catch{}};
function activity(xp){const d=today();if(S.lastDay!==d){const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);S.streak=S.lastDay===yesterday.toLocaleDateString('en-CA')?(S.streak||0)+1:1;S.lastDay=d}S.xp=Math.max(0,(S.xp||0)+xp);S.activity[d]=(S.activity[d]||0)+1;save();}
const toast=message=>{document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=message;document.body.appendChild(el);setTimeout(()=>el.remove(),3000)};
const areaFor=id=>D.areas.find(a=>a.id===id);
let route='home', selectedLesson=null, domain='Tous', query='', training={type:'practice',num:20,scope:'Tous',kind:'Tous'},session=null, auditIndex=0,auditSelection=null,auditRevealed=false,deckIndex=0,deckReveal=false,sortMode='all',mobileMenu=false,lessonTab=0,lessonStage=0;
const allLessons=[...D.foundations,...D.areas.map(a=>({...a,id:'PA-'+a.id,duration:12,summary:a.goal,topic:a.domainName}))];
const isMastered=id=>S.completed.includes(id)&&!!S.lessonMissions?.[id]?.passed;
const numCompleted=()=>allLessons.filter(l=>isMastered(l.id)).length, progress=()=>Math.round(numCompleted()/allLessons.length*100);
const allAnswers=()=>Object.values(S.attempts).reduce((s,a)=>s+a.length,0);
const rightAnswers=()=>Object.values(S.attempts).reduce((s,a)=>s+a.filter(x=>x.correct).length,0);
const accuracy=()=>allAnswers()?Math.round(100*rightAnswers()/allAnswers()):0;
const formatDate=s=>{try{return new Date(s+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'})}catch{return s}};
const daysLeft=()=>S.settings.target?Math.max(0,Math.ceil((new Date(S.settings.target+'T12:00:00')-new Date())/86400000)):null;
const badge=(a)=>`<span class="tag domain-${esc(a.domain||'CORE')}">${esc(a.domainName||a.topic||'Fondations')}</span>`;
const btn=(name,text,klass='primary')=>`<button class="${klass}" data-action="${name}">${text}</button>`;
const pbar=v=>`<div class="progress"><span style="width:${Math.max(0,Math.min(100,v))}%"></span></div>`;
const nav=[['home','Tableau de bord','home'],['learn','Parcours pédagogique','book'],['train','Quiz et examen blanc','zap'],['audit','Simulateur d’audit','shield'],['flash','Révisions espacées','repeat'],['library','Référentiel des 31 PA','grid'],['stats','Statistiques','chart'],['settings','Mon programme','settings']];
function sidebar(){return `<aside class="sidebar ${mobileMenu?'open':''}"><div class="brand"><div class="brandmark">C</div><div><div class="brandname">CMMI Academy</div><div class="brandsub">édition 2027</div></div></div><div class="navcap">Mon espace</div>${nav.map(([id,t,ic],i)=>`${i===5?'<div class="navcap">Ressources</div>':''}<button class="navbtn ${route===id?'active':''}" data-route="${id}">${ico(ic)} ${esc(t)}</button>`).join('')}<div class="sidebarFoot"><div class="tiny" style="font-size:11px">PROGRESSION GLOBALE</div><div style="display:flex;justify-content:space-between;align-items:center;margin:8px 0"><strong>${progress()}%</strong><span class="tiny" style="font-size:11px">${numCompleted()}/${allLessons.length} leçons</span></div>${pbar(progress())}<div class="tiny" style="font-size:10px">Parcours individuel • données locales</div></div></aside>`}
function topbar(){let t=nav.find(n=>n[0]===route)?.[1];return `<div class="topbar"><div class="breadcrumbs"><button class="mobiletoggle" data-action="menu" aria-label="Ouvrir le menu">${ico('menu')}</button><span>Mon espace</span><span>›</span><strong>${esc(t)}</strong></div><div class="topright"><span class="pill gold">${ico('flame',15)} ${S.streak||0} j</span><span class="pill blue">${ico('zap',14)} ${S.xp||0} XP</span><div class="avatar">C</div></div></div>`}
function heading(eye,title,sub,action=''){return `<div class="pagehead"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
const moduleItem=l=>`<div class="moduleRow" role="button" tabindex="0" data-lesson="${esc(l.id)}"><div class="numCircle ${isMastered(l.id)?'done':''}">${isMastered(l.id)?ico('check',17):esc(l.id.startsWith('PA-')?l.id.replace('PA-',''):l.id.substring(1))}</div><div><div class="moduletitle">${esc(l.title)}</div><div class="modulemeta">${esc(l.topic||l.domainName||'Cours')} · ${l.duration||12} min</div></div><span class="rowend" style="color:#90a3b3">${ico('arrow',16)}</span></div>`;
function home(){const next=allLessons.find(l=>!isMastered(l.id))||allLessons[0],r=D.questions.filter(q=>{const p=S.attempts[q.id]||[];return p.some(x=>!x.correct)}).length;
const stage=S.settings.track==='enterprise'?'évaluation d’entreprise':'examen individuel';
return `<section class="hero"><div class="heroText"><div class="eyebrow">TON PROGRAMME • CMMI V4.0</div><h2>Maîtrise les processus.<br>Prépare ton évaluation.</h2><p>Un apprentissage progressif et ludique pour préparer ${stage} en 2027. Théorie, ${D.questions.length} questions, cas pratiques et exercices d’audit.</p>${btn('continue',`Reprendre mon parcours ${ico('arrow')}`)}</div><div class="heroVisual"><div class="orbit"><i class="orb"></i></div><div class="orbit"></div><div class="heroCenter">${ico('shield',40)}<b>CMMI 4.0</b><span>LEARNING LAB</span></div></div></section>
<div class="stats4"><div class="card metric"><div class="metricIcon">${ico('book',22)}</div><div><strong>${numCompleted()}<span class="muted" style="font-size:14px">/${allLessons.length}</span></strong><small>Leçons terminées</small></div></div><div class="card metric"><div class="metricIcon orange">${ico('target',23)}</div><div><strong>${accuracy()}%</strong><small>Réponses correctes</small></div></div><div class="card metric"><div class="metricIcon purple">${ico('repeat',22)}</div><div><strong>${r}</strong><small>Notions à retravailler</small></div></div><div class="card metric"><div class="metricIcon blue">${ico('clock',22)}</div><div><strong>${daysLeft()===null?'2027':daysLeft()}</strong><small>${daysLeft()===null?'Date à préciser':'Jours jusqu’à l’objectif'}</small></div></div></div>
<div class="grid2"><div class="card"><div class="sectionbar"><h3>Ta prochaine étape</h3><button class="textlink" data-route="learn">Voir le parcours ${ico('arrow',13)}</button></div><div class="focus"><div class="eyebrow">À étudier ensuite</div><h3 style="margin:9px 0 5px;font-size:18px;color:#244255">${esc(next.title)}</h3><p style="color:#72899a;font-size:12px;line-height:1.7">${esc(next.summary||next.goal)}</p><div class="buttonsInline"><button class="primary btnsm" data-lesson="${esc(next.id)}">Ouvrir la leçon ${ico('arrow')}</button><span class="muted small">${next.duration||12} min</span></div></div><div class="sectionbar" style="margin-top:27px"><h3>Leçons recommandées</h3><span class="muted">Découverte</span></div>${allLessons.filter(l=>!isMastered(l.id)).slice(0,3).map(moduleItem).join('')}</div><div class="card"><div class="sectionbar"><h3>Ta préparation 2027</h3><span class="pill">${S.settings.level==='3'?'Objectif ML3':'Objectif ML'+esc(S.settings.level)}</span></div><div class="journey">${[['01','Comprendre les fondations','Architecture, terminologie, maturité'],['02','Explorer les 31 Practice Areas','Concepts, preuves et erreurs fréquentes'],['03','Maîtriser les situations','Questions à cas et décisions'],['04','Simuler l’audit','Entretiens, preuves et appréciation'],['05','Consolider les lacunes','Révisions espacées et examens blancs']].map(([n,t,d])=>`<div class="journeyItem"><div class="journeyMarker">${n}</div><div><b>${t}</b><p>${d}</p></div></div>`).join('')}</div><button class="secondary" style="width:100%;margin-top:10px" data-route="train">${ico('zap')} Faire un quiz rapide</button></div></div>
<div class="card" style="margin-top:19px"><div class="sectionbar"><h3>Mission du jour</h3><span class="pill gold">+20 XP</span></div><div style="display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap"><div><b style="font-size:13px">Tester tes acquis en 10 questions</b><p style="font-size:12px;color:#8392a5;margin-bottom:0">Révision active + feedback immédiat pour ancrer les connaissances.</p></div><button class="primary" data-action="quick">Commencer ${ico('arrow')}</button></div></div>`}
function learn(){let list=allLessons.filter(l=>domain==='Tous'||l.topic===domain||l.domainName===domain).filter(l=>(l.title+' '+(l.summary||'')+' '+l.id).toLowerCase().includes(query.toLowerCase()));let topics=['Tous','Fondations','Méthode d’audit','Maturité avancée',...Object.values(D.domainNames)];return heading('PARCOURS COMPLET','Apprendre, comprendre, maîtriser','39 cours approfondis : théorie guidée, schémas à explorer, cas d’entreprise et ateliers interactifs.')+`<div class="filterrow">${topics.map(t=>`<button class="chip ${domain===t?'active':''}" data-filter="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="filterrow"><input class="input search" type="search" id="lessonsearch" placeholder="Rechercher un sujet ou code PA…" value="${esc(query)}"/><span class="muted small">${list.length} modules trouvés</span></div><div class="catalog">${list.map(l=>`<div class="card lessonCard" data-lesson="${esc(l.id)}"><div class="lessonTop">${badge(l)}<span class="${isMastered(l.id)?'pill':'muted'}" style="font-size:10px">${isMastered(l.id)?'✓ Acquis':(l.duration||12)+' min'}</span></div><h3>${esc(l.title)}</h3><p>${esc(l.summary||l.goal)}</p><div class="lessonFooter"><span>${l.id.startsWith('PA-')?'PA · '+l.id.replace('PA-',''):'Module · '+l.id}</span><b>Étudier ${ico('arrow',13)}</b></div></div>`).join('')||'<div class="card noResults">Aucun module ne correspond à ta recherche.</div>'}</div>`}
function lesson(){
 const l=allLessons.find(x=>x.id===selectedLesson);
 if(!l){route='learn';return learn()}
 const a=l.id.startsWith('PA-')?areaFor(l.id.substring(3)):null;
 const deep=l.deep||a?.deep;
 if(!deep)return `<div class="card">Le contenu de cette leçon est indisponible. ${btn('continue','Retour au parcours')}</div>`;
 const isPA=!!a, next=allLessons[allLessons.indexOf(l)+1];
 const missions=S.lessonMissions||{};
 const passed=!!missions[l.id]?.passed;
 const tabs=[['Comprendre','book'],['Schéma & niveaux','grid'],['Étude de cas','shield'],['Atelier interactif','zap']];
 const para=s=>`<p class="coursep">${esc(s).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>')}</p>`;
 const sectionHead=(number,kicker,title,sub)=>`<div class="courseSectionHeader"><div class="courseCount">${number}</div><div><div class="eyebrow">${kicker}</div><h2>${title}</h2><p>${sub}</p></div></div>`;
 let content='';
 if(lessonTab===0){
 content=`${sectionHead('01','LES FONDAMENTAUX','Comprendre sans quitter la plateforme','Lecture guidée · tous les éléments essentiels de cette leçon sont ici.')}
 <div class="courseLead">${esc(deep.kicker)}</div><div class="courseCopy">${deep.paragraphs.map(para).join('')}</div>
 <div class="lessonMiniTitle">Ce qu’il faut retenir</div>
 <div class="insightPair"><div><span class="insightMark positive">✓ À démontrer</span><h4>Une pratique concrète, utilisée et vérifiable</h4><p>${esc(isPA?`Une action répond à l'objectif de ${a.id} ; ses traces et résultats expliquent comment elle fonctionne.`:'Relier les démarches CMMI aux résultats, au périmètre et aux preuves examinées.')}</p></div><div><span class="insightMark negative">× À éviter</span><h4>Confondre intention et exécution</h4><p>${esc(isPA?a.pitfall:'Un manuel, un score d’entraînement ou un slogan ne suffisent pas à démontrer la maturité organisationnelle.')}</p></div></div>
 ${l.id==='F04'?`<div class="lessonMiniTitle">Comparaison opérationnelle : qui évalue-t-on ?</div><div class="contrastGrid"><div><span class="insightMark positive">INDIVIDU · EXAMEN</span><p><b>Objet :</b> les connaissances et compétences d’une personne.</p><p><b>Éléments :</b> parcours requis, formation et épreuve.</p><p><b>Résultat :</b> credential individuel selon les règles applicables.</p></div><div><span class="insightMark positive">ORGANISATION · APPRAISAL</span><p><b>Objet :</b> des pratiques dans une unité organisationnelle définie.</p><p><b>Éléments :</b> portée, projets, acteurs et traces effectives.</p><p><b>Résultat :</b> constat ou niveau reconnu selon la méthode officielle.</p></div></div>`:''}
 <div class="conceptGrid">${deep.glossary.map(([term,def])=>`<div class="concept"><b>${esc(term)}</b><p>${esc(def)}</p></div>`).join('')}</div>`;
 }else if(lessonTab===1){
 const stages=deep.steps;
 const active=Math.min(lessonStage,stages.length-1);
 content=`${sectionHead('02','CARTE MENTALE ACTIVE','Voir le processus en action','Clique sur chacune des étapes pour comprendre l’enchaînement.')}
 <div class="diagramOuter"><div class="diagramEyebrow">SCHÉMA INTERACTIF · 4 ÉTAPES</div><div class="processDiagram">${stages.map(([name,detail],i)=>`<button data-lesson-stage="${i}" class="processNode ${active===i?'active':''}" aria-pressed="${active===i}"><span class="processN">${String(i+1).padStart(2,'0')}</span><b>${esc(name)}</b><span class="processConnector" aria-hidden="true">→</span></button>`).join('')}</div><div class="diagramExplanation"><span class="insightMark positive">Étape ${active+1} / ${stages.length}</span><h3>${esc(stages[active][0])}</h3><p>${esc(stages[active][1])}</p></div><div class="diagramNav"><button class="secondary btnsm" data-action="prevstage" ${active===0?'disabled':''}>← Étape précédente</button><button class="secondary btnsm" data-action="nextstage" ${active===stages.length-1?'disabled':''}>Étape suivante →</button></div></div>
 <div class="lessonMiniTitle">${isPA?'Évolution de cette Practice Area dans le guide v4.0':'Comment utiliser ce schéma'}</div>
 ${isPA?`<p class="small muted courseCaption">Les niveaux ci-dessous sont des reformulations pédagogiques du résumé officiel, et non les pratiques normatives complètes. Seuls les niveaux présents pour cette PA sont affichés.</p><div class="pgLevelList">${Object.entries(deep.levelFr||{}).map(([k,v])=>`<div class="pgLevel"><span class="pgNum">${k}</span><div><b>Practice Group · Niveau ${k}</b><p>${esc(v)}</p></div></div>`).join('')}</div>`:`<div class="courseCopy"><p class="coursep">Le schéma présente une démarche à explorer et à mettre en pratique. Pour chaque étape, demande-toi : quel rôle intervient, quelle décision est prise et quelle trace permet de vérifier qu’elle a été réalisée ?</p><p class="coursep">Ces étapes sont un outil pédagogique : elles n’ont pas valeur de procédure d’évaluation officielle.</p></div>`}`;
 }else if(lessonTab===2){
 content=`${sectionHead('03','DOSSIER D’ENTREPRISE','Observer, raisonner, décider','Une mise en situation fictive avec correction expliquée.')}
 <div class="caseStudy"><div class="caseStudyTop"><span class="tinyCase">DOSSIER D’ENTREPRISE · SIMULATION</span><span class="pill">${esc(isPA?a.id:l.id)}</span></div><h3>📁 La situation</h3>${para(deep.story)}<div class="caseTimeline"><div class="miniEvent"><span>1</span><div><b>Constat</b><p>${esc(isPA?a.symptom:l.challenge)}</p></div></div><div class="miniEvent"><span>2</span><div><b>Décision</b><p>${esc(isPA?a.response:deep.steps[2][1])}</p></div></div><div class="miniEvent"><span>3</span><div><b>Résultat attendu</b><p>${esc(isPA?`Vérifier les traces : ${a.expected.toLowerCase()}.`:deep.lesson)}</p></div></div></div></div>
 <div class="lessonMiniTitle">${isPA?'Ce qu’il faudrait trouver lors de la préparation':'Distinguer l’indice de la preuve'}</div>
 ${isPA?`<div class="evidenceList">${deep.evidenceExamples.map((v,i)=>`<div class="evidenceRow"><span>${ico(['book','check','search','chart'][i])}</span><p>${esc(v)}</p></div>`).join('')}</div><div class="contrastGrid"><div><span class="insightMark positive">Dossier étayé</span><p>${esc(deep.evidenceContrast[0])}</p></div><div><span class="insightMark negative">Dossier fragile</span><p>${esc(deep.evidenceContrast[1])}</p></div></div>`:`<div class="contrastGrid"><div><span class="insightMark positive">Raisonnement solide</span><p>${esc(deep.lesson)}</p></div><div><span class="insightMark negative">Erreur de diagnostic</span><p>${esc(l.bullets[0])} : ce repère, seul et sans recoupement, ne suffit pas à tirer une conclusion organisationnelle.</p></div></div>`}
 <details class="reasonReveal"><summary>Afficher la correction commentée</summary><div>${para(deep.lesson)}<p class="coursep">Dans une évaluation réelle, ces constats doivent être approfondis en fonction de la vue du modèle, des règles applicables et des preuves disponibles. Le scénario proposé reste fictif.</p></div></details>`;
 }else{
 const answer=missions[l.id]?.choice;
 const won=answer===deep.correct;
 const show=answer!==undefined;
 content=`${sectionHead('04','À TOI DE JOUER','Prends une décision','Choisis une solution, puis découvre le raisonnement et débloque les acquis.')}
 <div class="workshop"><div class="workshopTop"><span>🎮 MISSION ${esc(l.id)}</span><span class="pill gold">+15 XP · première réussite</span></div><h3>${esc(deep.question)}</h3><div class="workshopOptions">${deep.choices.map((v,i)=>`<button data-lesson-choice="${i}" class="workshopOption ${show&&answer===i?(i===deep.correct?'good':'bad'):''}" aria-pressed="${show&&answer===i}"><span class="choiceLabel">${String.fromCharCode(65+i)}</span><span>${esc(v)}</span>${show&&answer===i?ico(i===deep.correct?'check':'close',17):''}</button>`).join('')}</div>
 ${show?`<div class="workshopFeedback ${won?'correct':'incorrect'}"><b>${won?'✓ Décision validée !':'↻ Pas encore : analyse les conséquences et réessaie.'}</b><p>${esc(deep.why)}</p>${!won?'<button class="secondary btnsm" data-action="resetmission">Réessayer</button>':''}</div>`:'<p class="small muted" style="margin-top:16px">Tu peux répondre plusieurs fois. Les mauvaises réponses ne bloquent pas ta progression.</p>'}
 </div>${won?`<div class="missionAward">${ico('trophy',30)} <div><b>Mission accomplie</b><p>Tu peux maintenant valider la leçon et accéder aux questions de renforcement.</p></div></div>`:''}
 <div class="quizTeaser"><div><b>Tu veux aller plus loin ?</b><p>Teste le transfert de connaissances avec les QCM de ce sujet, sans quitter l’application.</p></div><button class="secondary" data-action="lessonquiz" data-area="${esc(isPA?a.id:l.id)}">${ico('target')} Lancer le quiz</button></div>`;
 }
 const sourceLabel=isPA?`Guide CMMI v4.0 · p. ${a.page}`:'Guide v4.0 et guide ISACA des certifications';
 const seen=(S.lessonVisited?.[l.id]||[0]).length;
 const percentage=isMastered(l.id)?100:passed?90:Math.min(75,Math.round(seen/4*75));
 const last=lessonTab===tabs.length-1;
 return `<button class="detailBack" data-route="learn">${ico('back')} Toutes les leçons</button>
 <div class="detailBanner deepBanner"><div><div class="eyebrow">${isPA?'PRATIQUE ORGANISATIONNELLE · V4.0':'FONDATIONS · COURS APPROFONDI'}</div><h1>${esc(l.title)}</h1><p>${esc(l.summary||l.goal)}</p><div class="bannerTags"><span class="pill">${l.duration||25} min de formation</span><span class="pill">${esc(l.topic||l.domainName)}</span><span class="pill">4 séquences + évaluation</span></div></div><div class="detailCode">${esc(isPA?a.id:l.id)}</div></div>
 <div class="studyProgress"><span>Ton avancée dans le chapitre</span><b>${percentage}%</b>${pbar(percentage)}</div>
 <div class="deepLayout"><div><div class="courseTabs" role="tablist" aria-label="Étapes de la leçon">${tabs.map(([label,icon],i)=>`<button role="tab" aria-selected="${lessonTab===i}" data-lesson-tab="${i}" class="courseTab ${lessonTab===i?'active':''}"><span class="tabNum">${i+1}</span>${label}</button>`).join('')}</div><article class="courseCard">${content}<div class="courseBottomNav"><button class="secondary" data-action="prevtab" ${lessonTab===0?'disabled':''}>${ico('back')} Précédent</button>${!last?`<button class="primary" data-action="nexttab">${tabs[lessonTab+1][0]} ${ico('arrow')}</button>`:`<div class="buttonsInline"><button class="secondary" data-action="complete" data-id="${esc(l.id)}" ${!passed?'disabled':''}>${isMastered(l.id)?'✓ Leçon validée':'✓ Valider la leçon · +20 XP'}</button>${next?`<button class="primary" data-lesson="${esc(next.id)}">Leçon suivante ${ico('arrow')}</button>`:''}</div>`}</div></article></div>
 <aside class="studyAside"><div class="card sideCourse"><div class="eyebrow">TON OBJECTIF</div><h3>${esc(isPA?'Appliquer '+a.id:'Maîtriser la notion')}</h3><p>${esc(l.summary||l.goal)}</p><div class="sideChecklist">${tabs.map(([label],i)=>`<button data-lesson-tab="${i}">${ico(i===lessonTab?'arrow':i<lessonTab?'check':'book',15)} ${esc(label)}</button>`).join('')}</div><div class="sideCourseStatus">${passed?'<b>✓ Activité réussie</b>':'<span>Activité finale à réussir avant validation.</span>'}</div><hr/><div class="eyebrow">POUR APPROFONDIR</div><p>${esc(sourceLabel)}. Ressource complémentaire facultative : toute la leçon et ses exercices se trouvent sur cette page.</p><a href="https://cmmiinstitute.com/resource-files/public/cmmi-model-quick-reference-guide" target="_blank" rel="noopener">Guide de référence ${ico('external',13)}</a>${isPA?'<p class="small muted" style="margin-top:13px">Les synthèses de niveaux sont des paraphrases pédagogiques, pas le modèle complet requis pour un appraisal.</p>':''}</div></aside></div>`;
}

function train(){const kinds=['Tous','concept','preuves','situation','piège','cartographie','audit','fondations','cas'];const track=S.settings.track==='enterprise';return heading('ENTRAÎNEMENT INTELLIGENT','Quiz et examens blancs',`${D.questions.length} questions originales, feedback explicatif et historique des scores.`)+`<div class="trainingTiles" style="margin-bottom:19px"><button class="trainTile" data-train-type="practice"><span class="tileIcon">🎯</span><b>Entraînement libre</b><p>Réponses et explications immédiatement. Travaille tes faiblesses.</p></button><button class="trainTile" data-train-type="exam"><span class="tileIcon">⏱️</span><b>Examen blanc</b><p>Temps limité, sans correction avant la fin. Score et bilan détaillés.</p></button><button class="trainTile" data-route="audit"><span class="tileIcon">🔎</span><b>Mission d’évaluateur</b><p>Examiner des dossiers, qualifier les preuves et décider d’actions.</p></button></div><div class="quizSetup"><div class="card"><div class="sectionbar"><h3>Configurer une session</h3><span class="tag">${training.type==='exam'?'Examen blanc':'Entraînement'}</span></div><div class="field"><label>Mode de session</label><div class="difficultyGrid"><button class="selectable ${training.type==='practice'?'active':''}" data-train-type="practice"><strong>🎯</strong><small>Quiz</small></button><button class="selectable ${training.type==='exam'?'active':''}" data-train-type="exam"><strong>⏱️</strong><small>Examen</small></button><button class="selectable" data-action="errors"><strong>🔁</strong><small>Mes erreurs</small></button></div></div><div class="field"><label>Questions par session</label><div class="difficultyGrid">${[10,20,40].map(n=>`<button class="selectable ${training.num===n?'active':''}" data-num="${n}"><strong>${n}</strong><small>questions</small></button>`).join('')}</div></div><div class="field"><label>Domaine à travailler</label><select class="select" id="trainScope"><option ${training.scope==='Tous'?'selected':''}>Tous</option>${Object.entries(D.domainNames).map(([k,v])=>`<option value="${esc(k)}" ${training.scope===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Type de question</label><select class="select" id="trainKind">${kinds.map(k=>`<option value="${esc(k)}" ${training.kind===k?'selected':''}>${esc(k==='Tous'?'Toutes les questions':({concept:'Concepts',preuves:'Preuves',situation:'Mises en situation','piège':'Erreurs à éviter',cartographie:'Cartographie',audit:'Audit',fondations:'Fondations',cas:'Cas pratiques'})[k])}</option>`).join('')}</select></div><button class="primary" style="width:100%" data-action="start">Démarrer la session ${ico('arrow')}</button><p class="muted" style="font-size:11px;line-height:1.6">${training.type==='exam'?'Examen simulé non officiel. Temps : '+Math.round(training.num*1.3)+' min.':'Feedback immédiat. Tes réponses alimentent les statistiques et révisions.'}</p></div><div class="card"><h3 style="font-size:17px;margin-top:0">Comment progresser efficacement ?</h3>${[['1','Comprends','Lis le cours en comprenant le pourquoi de la pratique.'],['2','Récupère','Fais un quiz sans regarder la correction.'],['3','Applique','Traite un cas d’entreprise et justifie ton jugement.'],['4','Répète','Revois tes erreurs les jours suivants.']].map(([i,t,d])=>`<div class="journeyItem"><div class="journeyMarker">${i}</div><div><b>${t}</b><p>${d}</p></div></div>`).join('')}<div class="notice" style="margin-top:20px">${track?'Parcours conseillé : analyse des preuves et préparation à un appraisal réel.':'Parcours conseillé : compréhension des concepts et examens blancs individuels.'}</div><button class="secondary" style="width:100%;margin-top:17px" data-route="flash">Voir les cartes à réviser ${ico('arrow')}</button></div></div>`}
function shuffle(xs){let a=[...xs];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function startQuiz(opts={}){const type=opts.type||training.type,scope=opts.scope||training.scope,kind=opts.kind||training.kind;let pool=D.questions.filter(q=>(scope==='Tous'||(areaFor(q.area)?.domain===scope)||q.area===scope||q.id.startsWith(scope+'-'))&&(kind==='Tous'||q.kind===kind));if(opts.ids)pool=D.questions.filter(q=>opts.ids.includes(q.id));if(!pool.length){toast('Aucune question disponible pour ce filtre.');return}const n=Math.min(opts.num||training.num,pool.length);session={type,pool:shuffle(pool).slice(0,n),idx:0,answers:[],selection:null,locked:false,started:Date.now(),deadline:type==='exam'?Date.now()+Math.round(n*1.3)*60000:null,done:false,source:opts.source||'session'};route='quiz';render();}
function sessionQuestion(){if(!session)return train();if(session.done)return quizResult();const q=session.pool[session.idx],a=session.answers.find(x=>x.i===session.idx),exam=session.type==='exam';const time=exam?Math.max(0,Math.ceil((session.deadline-Date.now())/1000)):null;return `<div class="quizLayout"><button class="detailBack" data-action="exitquiz">${ico('back')} Quitter la session</button><div class="card quizShell"><div class="quizProgress"><span><b>${exam?'EXAMEN BLANC':'ENTRAÎNEMENT'}</b> · Question ${session.idx+1} sur ${session.pool.length}</span><span>${exam?`⏱ <b id="timer">${Math.floor(time/60)}:${String(time%60).padStart(2,'0')}</b>`:`${Math.round((session.idx+1)/session.pool.length*100)} %`}</span></div>${pbar(session.idx/session.pool.length*100)}<div class="filterrow" style="margin:20px 0 2px"><span class="tag">${esc(q.kind)}</span><span class="muted small">Difficulté ${q.difficulty}/3</span>${q.area?`<span class="tag">${esc(q.area)}</span>`:''}</div><h2 class="quizQuestion">${esc(q.q)}</h2><div class="answers">${q.options.map((o,j)=>`<button class="answer ${session.selection===j?'chosen':''} ${a&&!exam&&j===q.answer?'correct':''} ${a&&!exam&&j===a.choice&&j!==q.answer?'wrong':''}" data-choose="${j}" ${a?'disabled':''}><span class="letter">${'ABCD'[j]}</span><span>${esc(o)}</span>${a&&!exam&&j===q.answer?'<span style="margin-left:auto;color:#148c64">✓</span>':''}</button>`).join('')}</div>${a&&!exam?`<div class="feedback ${a.correct?'':'bad'}"><b>${a.correct?'✓ Bonne réponse !':'✕ À revoir'}</b><div style="margin-top:5px">${esc(q.explanation)}</div></div>`:''}<div class="quizActions"><span class="muted small">${exam?'Correction à la fin':a?'Réponse enregistrée':'Choisis une seule réponse'}</span>${btn('nextquestion',session.idx===session.pool.length-1?'Terminer la session '+ico('check'):'Question suivante '+ico('arrow'),`primary ${session.selection===null?'disabledbutton':''}`)}</div></div><div class="muted" style="font-size:11px;text-align:center;margin-top:16px">Raccourcis : touches 1 à 4 pour répondre, Entrée pour continuer.</div></div>`}
function finishSession(){if(!session||session.done)return;session.done=true;const out=[];session.pool.forEach((q,i)=>{let a=session.answers.find(x=>x.i===i);if(!a)return;const answer={date:Date.now(),correct:a.correct,choice:a.choice};S.attempts[q.id]??=[];S.attempts[q.id].push(answer);if(S.attempts[q.id].length>25)S.attempts[q.id].shift();out.push({q,answer});if(q.area){const card=S.flash[q.area]||{ease:2.5,interval:0,due:0,streak:0};if(!a.correct){card.due=Date.now();card.streak=0}else if(!card.due){card.due=Date.now()+86400000}S.flash[q.area]=card}});let score=out.filter(x=>x.answer.correct).length,number=session.pool.length;S.scores.push({at:Date.now(),correct:score,total:number,type:session.type});S.scores=S.scores.slice(-200);activity(score*5+Math.round(score/Math.max(1,number)*20));session.finalRows=out;save();render()}
function quizResult(){const answered=session.finalRows||[],correct=answered.filter(x=>x.answer.correct).length,all=session.pool.length,percent=Math.round(correct/all*100);let wrong=answered.filter(x=>!x.answer.correct);return `<div class="quizLayout"><div class="card" style="text-align:center;padding:35px 25px"><div class="eyebrow">SESSION TERMINÉE</div><div class="resultScore">${percent}%</div><h2 style="margin:0 0 5px;font-size:24px">${percent>=85?'Excellent travail !':percent>=60?'Bonne progression !':'Continue à t’entraîner'}</h2><p class="muted" style="font-size:13px">${correct} bonnes réponses sur ${all} · ${session.type==='exam'?'Examen simulé':'Session libre'}</p>${pbar(percent)}<div class="buttonsInline" style="justify-content:center;margin:24px 0 12px">${btn('restart','Nouvelle session '+ico('arrow'))}${btn('toflash','Réviser mes erreurs','secondary')}${btn('exitquiz','Retour au tableau de bord','secondary')}</div></div><div class="card" style="margin-top:18px"><div class="sectionbar"><h3>Correction commentée</h3><span class="pill">${wrong.length} erreurs</span></div>${answered.length?answered.map(({q,answer},i)=>`<div class="review"><div style="display:flex;justify-content:space-between;gap:12px"><b>${i+1}. ${esc(q.q)}</b><span style="color:${answer.correct?'#22996e':'#c66b62'};font-weight:900">${answer.correct?'✓':'✕'}</span></div><p>Ta réponse : ${esc(q.options[answer.choice])}</p>${!answer.correct?`<p><b>Réponse attendue :</b> ${esc(q.options[q.answer])}</p>`:''}<p style="color:#33796b">${esc(q.explanation)}</p></div>`).join(''):'<div class="empty">Aucune réponse.</div>'}</div></div>`}
const dueAreas=()=>D.areas.filter(a=>!S.flash[a.id]||S.flash[a.id].due<=Date.now());
let currentDeck=[];
function cardsForReview(){return [...dueAreas(),...D.areas.filter(a=>S.flash[a.id]&&S.flash[a.id].due>Date.now())]}
function flash(){currentDeck=cardsForReview();if(deckIndex>=currentDeck.length)deckIndex=0;const a=currentDeck[deckIndex],due=dueAreas().length;return heading('RÉPÉTITION ESPACÉE','Flashcards intelligentes','Mémorise durablement les 31 pratiques grâce aux rappels programmés.')+`<div class="grid2"><div><div class="card" style="margin-bottom:15px"><div class="sectionbar"><h3>Carte ${deckIndex+1} / ${currentDeck.length}</h3><span class="pill">${due} à revoir aujourd’hui</span></div><p class="muted small" style="margin:0">Récite l’objectif, les preuves et l’erreur à éviter avant de retourner la carte.</p></div><div class="deck ${deckReveal?'revealed':''}" data-action="flip" role="button" tabindex="0"><div class="deckLabel">${deckReveal?'RÉPONSE':'À TOI DE JOUER'}</div>${deckReveal?`<div><h2>${esc(a.title)}</h2><p style="font-size:14px;line-height:1.7">${esc(a.goal)}</p><p style="font-size:12px;color:#bde5dd">Preuves : ${esc(a.expected)}</p></div>`:`<h2>Que signifie <b style="color:#8be2d1">${esc(a.id)}</b> et comment le démontrer lors d’un audit ?</h2>`}<small>Cliquer pour retourner la carte</small></div>${deckReveal?`<div class="flashcontrols"><button class="secondary" data-review="again">🔁 À revoir</button><button class="secondary" data-review="good">👍 Bien</button><button class="primary" data-review="easy">✨ Facile</button></div>`:`<div class="flashcontrols"><button class="primary" data-action="flip">Voir la réponse ${ico('arrow')}</button></div>`}</div><div class="card"><h3 style="margin-top:0">Comment ça fonctionne ?</h3><p class="small muted" style="line-height:1.75">Tu évalues ton souvenir. Les cartes difficiles reviennent plus tôt ; les cartes bien assimilées sont espacées automatiquement. Les erreurs aux quiz les réactivent.</p><div class="journeyItem"><div class="journeyMarker">1</div><div><b>À revoir</b><p>La carte réapparaît très bientôt.</p></div></div><div class="journeyItem"><div class="journeyMarker">2</div><div><b>Bien</b><p>Intervalle progressivement plus long.</p></div></div><div class="journeyItem"><div class="journeyMarker">3</div><div><b>Facile</b><p>Échéance plus éloignée.</p></div></div><div class="notice">Cette répétition espacée est pédagogique ; elle ne remplace pas la pratique en entreprise.</div></div></div>`}
function reviewCard(grade){const a=currentDeck[deckIndex];if(!a)return;let x=S.flash[a.id]||{ease:2.5,interval:0,due:0,streak:0};if(grade==='again'){x.interval=0;x.streak=0;x.ease=Math.max(1.3,x.ease-.2);x.due=Date.now()+10*60000}else{ x.streak++;x.interval=x.streak===1?(grade==='easy'?3:1):x.streak===2?(grade==='easy'?8:3):Math.max(4,Math.round(x.interval*(grade==='easy'?x.ease*1.25:x.ease)));x.ease=Math.max(1.3,x.ease+(grade==='easy'?.12:0));x.due=Date.now()+x.interval*86400000;}S.flash[a.id]=x;activity(grade==='again'?1:grade==='easy'?6:4);deckReveal=false;deckIndex=(deckIndex+1)%currentDeck.length;render();toast('Carte programmée pour révision.')}
function audit(){const c=D.cases[auditIndex%D.cases.length],done=Object.keys(S.auditAnswers).length,correct=Object.entries(S.auditAnswers).filter(([id,v])=>D.cases.find(c=>c.id===id)?.rating===v).length;return heading('MISSION D’ÉVALUATEUR','Simulateur d’audit CMMI','Analyse les preuves d’une entreprise fictive et apprends à distinguer les lacunes.','<button class="secondary" data-route="matrix">Mon diagnostic des 31 PA '+ico('arrow')+'</button>')+`<div class="auditgrid"><div class="card auditCase"><div class="sectionbar"><span class="tag">DOSSIER ${auditIndex+1} / ${D.cases.length}</span><span class="muted small">${esc(c.topic)}</span></div><h2>${esc(c.title)}</h2><p style="font-size:12px;color:#8a98a7;margin-bottom:10px">Compte rendu d’entretien ou pièce d’entreprise</p><div class="auditEvidence">“${esc(c.description)}”</div><h3 style="font-size:16px;margin:25px 0 4px">Quelle est la qualité de cette preuve ?</h3><p class="muted small">Juge uniquement les informations fournies, puis ouvre la correction.</p><div class="auditResponse">${['Preuve solide','Preuve partielle','Preuve insuffisante'].map(t=>`<button class="rating ${auditSelection===t?'active':''}" data-audit-rate="${t}" ${auditRevealed?'disabled':''}>${esc(t)}</button>`).join('')}</div><div class="field"><label>Note personnelle d’audit (facultatif)</label><textarea class="textarea" id="auditNote" placeholder="Quels entretiens, documents ou résultats demanderais-tu ?">${esc(S.auditNotes[c.id]||'')}</textarea></div>${auditRevealed?`<div class="feedback ${auditSelection===c.rating?'':'bad'}"><b>${auditSelection===c.rating?'✓ Bien évalué':'✕ Évaluation à revoir'} — ${esc(c.rating)}</b><p>${esc(c.reason)}</p><b>Action préconisée :</b> ${esc(c.action)}</div>`:''}<div class="auditNext"><button class="secondary" data-action="prevcase" ${auditIndex===0?'disabled':''}>${ico('back')} Précédent</button><button class="primary" data-action="${auditRevealed?'nextcase':'validatecase'}" ${!auditRevealed&&!auditSelection?'disabled':''}>${auditRevealed?'Dossier suivant':'Valider mon évaluation'} ${ico('arrow')}</button></div></div><div class="card auditSide"><div class="sectionbar"><h3>Rapport de mission</h3><span class="pill">+10 XP / dossier</span></div><div class="stats4" style="grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px"><div style="padding:14px;background:#f5faf9;border-radius:11px"><div class="statbig">${done}</div><span class="muted small">Analysés</span></div><div style="padding:14px;background:#f5faf9;border-radius:11px"><div class="statbig">${done?Math.round(100*correct/done):0}%</div><span class="muted small">Pertinence</span></div></div><h4 style="font-size:13px">Méthode de l'évaluateur</h4><ol><li>Lire le cas sans présupposé.</li><li>Distinguer description, déclaration et preuve.</li><li>Rechercher des traces représentatives.</li><li>Documenter les lacunes et questions.</li><li>Ne jamais attribuer un niveau officiel depuis cet exercice.</li></ol><hr/><p class="muted small" style="line-height:1.65">Ces dossiers et jugements pédagogiques sont fictifs et simplifiés. Ils ne reproduisent pas la méthode d’évaluation officielle ni une décision d’appraiser certifié.</p><button class="secondary" data-route="matrix" style="width:100%">Ouvrir la grille de préparation</button></div></div>`}
function matrix(){const vals=['Non évalué','Absent','Partiel','Solide'];const ready=D.areas.filter(a=>S.auditMatrix[a.id]==='Solide').length;return heading('AUTO-DIAGNOSTIC','Grille de préparation à l’appraisal','Inventorie les preuves des 31 PA. Le score ne constitue pas une notation CMMI officielle.','<button class="secondary" data-action="matrixcsv">'+ico('download')+' Exporter CSV</button>')+`<div class="card" style="margin-bottom:17px"><div class="sectionbar"><h3>Inventaire de preuves</h3><b style="color:#208a7b">${ready} / 31 pratiques avec preuves solides</b></div>${pbar(ready/31*100)}<p class="muted small">Notation auto-déclarée : « solide » signifie seulement que tu estimes posséder des preuves à faire confirmer. Le périmètre d’une vraie évaluation peut différer.</p></div><div class="card" style="overflow-x:auto"><table class="matrix"><thead><tr><th>Code</th><th>Practice Area</th><th>Domaine</th><th>Qualité des preuves</th></tr></thead><tbody>${D.areas.map(a=>`<tr><td><b>${esc(a.id)}</b></td><td><a href="#" data-lesson="PA-${esc(a.id)}" style="text-decoration:none;color:#27465a;font-weight:700">${esc(a.title)}</a></td><td>${esc(a.domainName)}</td><td><select class="dropdown" data-matrix="${esc(a.id)}">${vals.map(v=>`<option ${S.auditMatrix[a.id]===v?'selected':''}>${v}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`}
function library(){let list=D.areas.filter(a=>(domain==='Tous'||domain===a.domain)&&((a.id+' '+a.title+' '+a.goal+' '+a.domainName).toLowerCase().includes(query.toLowerCase())));return heading('RÉFÉRENTIEL V4.0','Les 31 Practice Areas','Définitions pédagogiques, preuves typiques, risques et correspondance aux domaines.')+`<div class="filterrow">${['Tous',...Object.keys(D.domainNames)].map(d=>`<button class="chip ${domain===d?'active':''}" data-filter="${d}">${esc(d==='Tous'?'Tous':D.domainNames[d])}</button>`).join('')}</div><div class="filterrow"><input class="input search" type="search" id="librarysearch" value="${esc(query)}" placeholder="Chercher code, domaine, mot-clé…"/><span class="muted small">${list.length} / 31 PA</span></div><div class="catalog">${list.map(a=>`<div class="card lessonCard" data-lesson="PA-${a.id}"><div class="lessonTop">${badge(a)}<span class="badgeNum">${a.id}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.goal)}</p><div class="lessonFooter"><span>Guide v4.0 · p. ${a.page}</span><b>Fiche complète ${ico('arrow',13)}</b></div></div>`).join('')||'<div class="card noResults">Aucun résultat trouvé.</div>'}</div><div class="notice" style="margin-top:18px">Le guide de référence est une synthèse et ne remplace pas le modèle complet, les règles de portée ou la méthode d’appraisal. Les descriptions et exemples de cette application sont des reformulations pédagogiques originales.</div>`}
function stats(){let byDomain=Object.entries(D.domainNames).map(([code,name])=>{const qs=D.questions.filter(q=>q.area&&areaFor(q.area)?.domain===code);const attempts=qs.flatMap(q=>S.attempts[q.id]||[]);return {code,name,n:attempts.length,rate:attempts.length?Math.round(100*attempts.filter(x=>x.correct).length/attempts.length):0}});let recent=S.scores.slice(-10);let days=[];for(let n=27;n>=0;n--){let dt=new Date();dt.setDate(dt.getDate()-n);let date=dt.toLocaleDateString('en-CA');days.push(S.activity[date]||0)}return heading('TON ÉVOLUTION','Analyse de progression','Mesure tes acquis et identifie précisément les sujets à renforcer.')+`<div class="stats4"><div class="card metric"><div class="metricIcon">${ico('check',22)}</div><div><strong>${allAnswers()}</strong><small>Réponses données</small></div></div><div class="card metric"><div class="metricIcon orange">${ico('target',22)}</div><div><strong>${accuracy()}%</strong><small>Précision globale</small></div></div><div class="card metric"><div class="metricIcon blue">${ico('trophy',22)}</div><div><strong>${S.scores.length}</strong><small>Sessions terminées</small></div></div><div class="card metric"><div class="metricIcon purple">${ico('flame',22)}</div><div><strong>${S.streak||0}</strong><small>Jours consécutifs</small></div></div></div><div class="split"><div class="card"><h3 style="margin-top:0">Précision par domaine</h3>${byDomain.map(d=>`<div style="margin:19px 0"><div style="display:flex;justify-content:space-between;margin-bottom:6px;font-size:12px"><b>${esc(d.name)}</b><span class="muted">${d.n?d.rate+' %':'—'} · ${d.n} réponses</span></div>${pbar(d.rate)}</div>`).join('')}</div><div class="card"><h3 style="margin-top:0">Tes 28 derniers jours</h3><div class="heat">${days.map(n=>`<span class="${n>=5?'c3':n>=2?'c2':n>=1?'c1':''}" title="${n} activité(s)"></span>`).join('')}</div><p class="muted small">Chaque carré correspond à un jour d’activité.</p><hr/><h3>Dernières sessions</h3>${recent.length?recent.reverse().map(s=>`<div class="resultArea"><span>${new Date(s.at).toLocaleDateString('fr-FR')} · ${s.type==='exam'?'Examen':'Entraînement'}</span><b>${Math.round(100*s.correct/s.total)}% (${s.correct}/${s.total})</b></div>`).join(''):'<p class="muted small">Aucune session terminée. Lance ton premier quiz !</p>'}<button class="primary" style="margin-top:20px;width:100%" data-route="train">Continuer à m’entraîner</button></div></div>`}
function settings(){return heading('PRÉPARATION PERSONNALISÉE','Mon programme 2027','Adapte ton parcours, sauvegarde tes données et consulte les références officielles.')+`<div class="split"><div><div class="card"><h3 style="margin-top:0">Objectif de préparation</h3><div class="field"><label>Que prépares-tu ?</label><select class="select" id="track"><option value="enterprise" ${S.settings.track==='enterprise'?'selected':''}>Évaluation CMMI d’une organisation (appraisal)</option><option value="personal" ${S.settings.track==='personal'?'selected':''}>Examen de certification individuelle</option></select></div><div class="field"><label>Niveau de maturité cible (pour les exercices)</label><select class="select" id="level">${[2,3,4,5].map(n=>`<option value="${n}" ${S.settings.level==n?'selected':''}>Niveau ${n}</option>`).join('')}</select></div><div class="field"><label>Date cible de préparation (facultative)</label><input id="goaldate" class="input" type="date" value="${esc(S.settings.target)}"/></div>${btn('savesettings','Enregistrer les préférences')}</div><div class="card" style="margin-top:17px"><h3 style="margin-top:0">Mes données</h3><p class="muted small">La progression est sauvegardée uniquement dans ce navigateur. Exporter le fichier JSON permet de la transférer ou de la sauvegarder.</p><div class="buttonsInline"><button class="secondary" data-action="export">${ico('download')} Exporter JSON</button><label class="secondary" style="cursor:pointer">${ico('upload')} Importer JSON <input type="file" id="importfile" accept=".json,application/json" hidden/></label><button class="secondary danger" data-action="reset">Tout réinitialiser</button></div></div></div><div><div class="card"><div class="sectionbar"><h3>Sources et limites</h3><span class="tag">Officiel vs entraînement</span></div>${[['Guide CMMI Model v4.0 — août 2026','Référence synthétique des 31 Practice Areas, fournie dans cette conversation.','https://cmmiinstitute.com/resource-files/public/cmmi-model-quick-reference-guide'],['CMMI Credentialing Guide — août 2026','Guide plus récent pour les certifications Practitioner et AIM. À privilégier pour les conditions d’examen 2027.','https://cmmiinstitute.com/resource-files/public/cmmi-model-materials/cmmi-credentialing-guide-for-practitioners'],['Guide Adoption for Credentials — 2024','Document fourni, utile à titre historique : ne pas extrapoler ses règles à 2027.','https://cmmiinstitute.com/learning/training'],['Model Viewer officiel','Modèle complet, détails des pratiques et vues applicables à l’appraisal.','https://www.cmmiinstitute.com/products/cmmi/cmmi-model-viewer']].map(([t,d,u])=>`<div class="source"><div class="sourceIcon">${ico('book')}</div><div><b>${esc(t)}</b><p>${esc(d)}</p><a href="${u}" target="_blank" rel="noopener">Accéder à la source ${ico('external',13)}</a></div></div>`).join('')}<div class="notice">Application indépendante, non affiliée à ISACA ou au CMMI Institute. Le modèle complet n'est pas reproduit ici. Aucune simulation ne remplace la formation requise, les textes actuels ou un appraisal officiel.</div></div></div></div>`}
const view=()=>route==='home'?home():route==='learn'?selectedLesson?lesson():learn():route==='train'?train():route==='quiz'?sessionQuestion():route==='flash'?flash():route==='audit'?audit():route==='matrix'?matrix():route==='library'?library():route==='stats'?stats():route==='settings'?settings():home();
function render(){document.title='CMMI Academy 2027 — Apprendre, pratiquer, évaluer';document.getElementById('root').innerHTML=`<div class="app">${sidebar()}<main class="main">${topbar()}<div class="content">${view()}<footer class="footer">© CMMI Academy · outil pédagogique indépendant · CMMI® est une marque du CMMI Institute · données conservées localement · révision : octobre 2026</footer></div></main></div>`;}
function routeTo(next){route=next;selectedLesson=null;mobileMenu=false;query='';domain='Tous';scrollTo(0,0);render()}
function dl(filename,content,type='application/json'){let blob=new Blob([content],{type}),url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2500)}
function prevNextQuiz(){if(!session||session.done)return;const q=session.pool[session.idx];if(session.selection===null){toast('Choisis une réponse avant de continuer.');return}let answer=session.answers.find(x=>x.i===session.idx);if(!answer){session.answers.push({i:session.idx,choice:session.selection,correct:session.selection===q.answer});if(session.type!=='exam'){render();return}}if(session.idx===session.pool.length-1)finishSession();else{session.idx++;session.selection=null;render()}}
function answerQuiz(choice){if(!session||session.done||session.answers.some(x=>x.i===session.idx))return;session.selection=choice;if(session.type!=='exam'){session.answers.push({i:session.idx,choice,correct:choice===session.pool[session.idx].answer})}render()}
let tmr=setInterval(()=>{if(route!=='quiz'||!session||session.done||session.type!=='exam')return;let left=Math.max(0,Math.ceil((session.deadline-Date.now())/1000));let tm=$('#timer');if(tm)tm.textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;if(left===0)finishSession()},1000);
document.addEventListener('click',e=>{
 const r=e.target.closest('[data-route]');if(r){e.preventDefault();routeTo(r.dataset.route);return}
 const l=e.target.closest('[data-lesson]');if(l){e.preventDefault();selectedLesson=l.dataset.lesson;lessonTab=0;lessonStage=0;route='learn';mobileMenu=false;scrollTo(0,0);render();return}
 const filter=e.target.closest('[data-filter]');if(filter){domain=filter.dataset.filter;render();return}
 const tt=e.target.closest('[data-train-type]');if(tt){training.type=tt.dataset.trainType;render();return}
 const lt=e.target.closest('[data-lesson-tab]');if(lt){lessonTab=Number(lt.dataset.lessonTab);if(selectedLesson){S.lessonVisited=S.lessonVisited||{};S.lessonVisited[selectedLesson]=[...new Set([...(S.lessonVisited[selectedLesson]||[0]),lessonTab])];save()}render();window.scrollTo({top:200,behavior:'smooth'});return}
 const ls=e.target.closest('[data-lesson-stage]');if(ls){lessonStage=Number(ls.dataset.lessonStage);render();return}
 const lc=e.target.closest('[data-lesson-choice]');if(lc){const v=Number(lc.dataset.lessonChoice);const k=selectedLesson;const l=allLessons.find(x=>x.id===k);const ok=v===l.deep.correct;S.lessonMissions=S.lessonMissions||{};const previous=S.lessonMissions[k]?.passed;if(ok&&!previous)activity(15);S.lessonMissions[k]={choice:v,passed:ok||previous||false};save();render();return}
 const nn=e.target.closest('[data-num]');if(nn){training.num=Number(nn.dataset.num);render();return}
 const choose=e.target.closest('[data-choose]');if(choose){answerQuiz(Number(choose.dataset.choose));return}
 const rating=e.target.closest('[data-audit-rate]');if(rating&&!auditRevealed){auditSelection=rating.dataset.auditRate;render();return}
 const rev=e.target.closest('[data-review]');if(rev){reviewCard(rev.dataset.review);return}
 const action=e.target.closest('[data-action]');if(!action)return;const a=action.dataset.action;
 if(a==='prevtab'){lessonTab=Math.max(0,lessonTab-1);if(selectedLesson){S.lessonVisited=S.lessonVisited||{};S.lessonVisited[selectedLesson]=[...new Set([...(S.lessonVisited[selectedLesson]||[0]),lessonTab])];save()}render();window.scrollTo({top:200,behavior:'smooth'});return}
 if(a==='nexttab'){lessonTab=Math.min(3,lessonTab+1);if(selectedLesson){S.lessonVisited=S.lessonVisited||{};S.lessonVisited[selectedLesson]=[...new Set([...(S.lessonVisited[selectedLesson]||[0]),lessonTab])];save()}render();window.scrollTo({top:200,behavior:'smooth'});return}
 if(a==='prevstage'){lessonStage=Math.max(0,lessonStage-1);render();return}
 if(a==='nextstage'){lessonStage=Math.min(3,lessonStage+1);render();return}
 if(a==='resetmission'){if(selectedLesson&&S.lessonMissions?.[selectedLesson]){delete S.lessonMissions[selectedLesson].choice;save();render()}return}
 if(a==='menu'){mobileMenu=!mobileMenu;render();return}
 if(a==='continue'){const n=allLessons.find(l=>!isMastered(l.id))||allLessons[0];selectedLesson=n.id;lessonTab=0;lessonStage=0;route='learn';render();return}
 if(a==='complete'){let id=action.dataset.id;if(!S.lessonMissions?.[id]?.passed){toast('Réussis d’abord l’atelier interactif de cette leçon.');return}if(!S.completed.includes(id)){S.completed.push(id);activity(20);toast('Leçon terminée ! +20 XP')}else toast('Leçon déjà terminée.');render();return}
 if(a==='lessonquiz'){let ar=action.dataset.area;startQuiz({scope:ar,num:ar.startsWith('F')?4:7,type:'practice'});return}
 if(a==='start'){training.scope=$('#trainScope')?.value||'Tous';training.kind=$('#trainKind')?.value||'Tous';startQuiz();return}
 if(a==='quick'){startQuiz({type:'practice',num:10,scope:'Tous',kind:'Tous'});return}
 if(a==='errors'){const ids=D.questions.filter(q=>(S.attempts[q.id]||[]).some(a=>!a.correct)).map(q=>q.id);if(!ids.length){toast('Aucune erreur enregistrée pour le moment.');return}startQuiz({ids,num:Math.min(20,ids.length),type:'practice'});return}
 if(a==='nextquestion'){prevNextQuiz();return}
 if(a==='exitquiz'){routeTo('train');return}
 if(a==='restart'){routeTo('train');return}
 if(a==='toflash'){routeTo('flash');return}
 if(a==='flip'){deckReveal=!deckReveal;render();return}
 if(a==='validatecase'){if(!auditSelection)return;let c=D.cases[auditIndex%D.cases.length];let note=$('#auditNote')?.value||'';S.auditNotes[c.id]=note;const first=!S.auditAnswers[c.id];S.auditAnswers[c.id]=auditSelection;auditRevealed=true;if(first)activity(auditSelection===c.rating?10:3);save();render();return}
 if(a==='nextcase'){auditIndex=(auditIndex+1)%D.cases.length;auditSelection=null;auditRevealed=false;render();return}
 if(a==='prevcase'){auditIndex=Math.max(0,auditIndex-1);auditSelection=null;auditRevealed=false;render();return}
 if(a==='matrixcsv'){let lines=['Code,Practice Area,Domaine,Evaluation',...D.areas.map(x=>[x.id,'"'+x.title.replaceAll('"','""')+'"',x.domainName,S.auditMatrix[x.id]||'Non évalué'].join(','))];dl('cmmi-grille-preuves.csv','\ufeff'+lines.join('\n'),'text/csv;charset=utf-8');toast('Grille CSV téléchargée.');return}
 if(a==='savesettings'){S.settings.track=$('#track').value;S.settings.level=$('#level').value;S.settings.target=$('#goaldate').value||'';save();toast('Préférences enregistrées.');render();return}
 if(a==='export'){dl('cmmi-academy-progression.json',JSON.stringify({app:'CMMI Academy',version:1,exportedAt:new Date().toISOString(),progress:S},null,2));return}
 if(a==='reset'){if(confirm('Supprimer toute ta progression dans ce navigateur ?')){S=defaultState();save();routeTo('home');toast('Progression réinitialisée.')}return}
});
document.addEventListener('input',e=>{if(e.target.id==='auditNote'){S.auditNotes[D.cases[auditIndex%D.cases.length].id]=e.target.value;save();return}if(e.target.id==='lessonsearch'||e.target.id==='librarysearch'){const val=e.target.value;query=val;let fieldId=e.target.id;let pos=e.target.selectionStart;render();const f=document.getElementById(fieldId);if(f){f.focus();f.setSelectionRange(pos,pos)}}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.matrix){S.auditMatrix[t.dataset.matrix]=t.value;save();render()}if(t.id==='trainScope')training.scope=t.value;if(t.id==='trainKind')training.kind=t.value;if(t.id==='importfile'&&t.files?.[0]){try{let v=JSON.parse(await t.files[0].text());if(v.app!=='CMMI Academy'||!v.progress||!Array.isArray(v.progress.completed))throw Error('Fichier non reconnu');S={...defaultState(),...v.progress,settings:{...defaultState().settings,...v.progress.settings}};save();render();toast('Progression importée.')}catch(err){toast('Import impossible : '+err.message)}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&mobileMenu){mobileMenu=false;render();return}if(e.target.matches('input,textarea,select'))return;if(route==='quiz'&&session&&!session.done){if(['1','2','3','4'].includes(e.key))answerQuiz(Number(e.key)-1);if(e.key==='Enter')prevNextQuiz()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-lesson],[data-action="flip"]')){e.preventDefault();e.target.click()}});
render();
})();
